MATCH (s:Set)
WHERE EXISTS {
  MATCH (s)-[e:CONTAINS*1..6 (r, n | WHERE r.version = (MATCH (s)-[x:CONTAINS]->() RETURN max(x.version)))]->(m:Minifig {fig_num: 'fig-001375'})
}
AND EXISTS {
  MATCH (s)-[e:CONTAINS*1..6 (r, n | WHERE r.version = (MATCH (s)-[x:CONTAINS]->() RETURN max(x.version)))]->(p:Part {part_num: '3298'})
  WHERE r.is_spare = false
}
RETURN count(DISTINCT s) AS set_count
```

```cypher
MATCH (s:Set)
WITH s, (MATCH (s)-[x:CONTAINS]->() RETURN max(x.version)) AS cur
WHERE EXISTS {
  MATCH (s)-[e:CONTAINS*1..6 (r, n | WHERE r.version = cur)]->(m:Minifig {fig_num: 'fig-001375'})
}
AND EXISTS {
  MATCH (s)-[e:CONTAINS*1..6 (r, n | WHERE r.version = cur AND r.is_spare = false)]->(p:Part {part_num: '3298'})
}
RETURN count(DISTINCT s) AS set_count
```

