```cypher
MATCH (s:Set)-[:IN_THEME]->(t:Theme)
WHERE s.year = 2013
  AND (t.name = 'Christmas' OR EXISTS {
    MATCH (t)-[:SUBTHEME_OF*1..10]->(parent:Theme)
    WHERE parent.name = 'Christmas'
  })
RETURN COUNT(DISTINCT s) AS count;
```

```cypher
MATCH (s:Set)-[:IN_THEME]->(t:Theme)
WHERE s.year = 2014
  AND (t.name = 'Duplo' OR EXISTS {
    MATCH (t)-[:SUBTHEME_OF*1..10]->(parent:Theme)
    WHERE parent.name = 'Duplo'
  })
RETURN count(DISTINCT s) AS num_sets;
```

```cypher
MATCH (t:Theme)
WHERE NOT EXISTS { MATCH (t)-[:SUBTHEME_OF]->(:Theme) }
MATCH (s:Set)-[:IN_THEME]->(sub:Theme)
WHERE s.year = 2019
  AND EXISTS { MATCH (sub)-[:SUBTHEME_OF*0..]->(t) }
RETURN t.name AS theme_name, COUNT(DISTINCT s) AS num_sets
ORDER BY num_sets DESC, t.name ASC
LIMIT 3;
```

