MATCH (p:Part {part_num: '88001'})
MATCH (s:Set)
WHERE EXISTS {
    MATCH (s)-[e:CONTAINS*1..15 {is_spare: false}]->(p)
    WHERE ALL(rel IN rels(e) WHERE NOT EXISTS {
        MATCH (sn)-[r:CONTAINS {is_spare: false}]->()
        WHERE sn = startNode(rel) AND r.version > rel.version
    })
}
RETURN COUNT(DISTINCT s) AS num_sets
