WHERE EXISTS {
    MATCH (targetSet)-[:CONTAINS*1..10 (r, n | WHERE r.is_spare = false)]->(m:Minifig {fig_num: 'fig-013416'})
}
WITH targetSet
WHERE EXISTS {
