```cypher
MATCH (s:Set {set_num: '71024-7'})
WITH s,
     // Get the current version of this set
     max([v IN [()-[r:CONTAINS]->() WHERE r.version IS NOT NULL | r.version]][]) AS current_version
WITH s, current_version

// Calculate total parts from all levels (excluding spare parts)
// First, get all paths from set to parts through nested sets and minifigs
MATCH path = (s)-[e:CONTAINS*1..10 (r, n | WHERE r.is_spare = false)]->(p:Part)
WHERE all(r IN rels(e) WHERE r.is_spare = false)
WITH s, current_version,
     // Check if first edge is from the set itself (direct part) or through nested items
     // We need to separate: direct parts in set's inventory vs parts from nested sets/minifigs
     collect({
       edges: rels(e),
       qty_list: properties(rels(e), 'qty'),
       is_direct: length(e) = 1 AND startNode(e[0]) = s
     }) AS all_paths

// Calculate total quantity for all paths
UNWIND all_paths AS path_info
WITH s, current_version, path_info,
     list_product(path_info.qty_list) AS total_qty

// Separate direct vs indirect (from nested sets/minifigs)
WITH s, current_version,
     sum(CASE WHEN path_info.is_direct THEN total_qty ELSE 0 END) AS direct_qty,
     sum(CASE WHEN NOT path_info.is_direct THEN total_qty ELSE 0 END) AS indirect_qty

// Handle case where there might be no parts at all
WITH s, current_version, 
     coalesce(direct_qty, 0) AS direct_qty,
     coalesce(indirect_qty, 0) AS indirect_qty

WITH s, current_version, direct_qty, indirect_qty, (direct_qty + indirect_qty) AS total_qty

// Calculate percentage from nested sets and minifigs
RETURN CASE WHEN total_qty = 0 THEN 0.00 ELSE round((indirect_qty * 100.0 / total_qty) * 100) / 100 END AS percentage_from_nested
```

