MATCH (s:Set {set_num: '70149-1'})
WITH s,
     // Get max version for the set's own inventory
     (MATCH (s)-[e:CONTAINS]->() RETURN max(e.version) AS max_v) AS own_max_version
WITH s, own_max_version.max_v AS own_max_v
// Calculate total parts from all levels (excluding spare parts)
CALL {
    WITH s
    MATCH path = (s)-[e:CONTAINS*1..10 (r, n | WHERE r.is_spare = false)]->(p:Part)
    WHERE all(r IN rels(e) WHERE r.is_spare = false)
    RETURN sum(list_product(properties(rels(e), 'qty'))) AS total_all_levels
} 
// Calculate parts directly in set's own inventory (not from nested sets/minifigs)
CALL {
    WITH s, own_max_v
    MATCH (s)-[e:CONTAINS {version: own_max_v}]->(p:Part)
    WHERE e.is_spare = false
    RETURN sum(e.qty) AS direct_parts
}
// Calculate parts from nested sets and minifigs (total - direct)
WITH total_all_levels, direct_parts, (total_all_levels - direct_parts) AS indirect_parts
WHERE total_all_levels > 0
RETURN round(indirect_parts * 100.0 / total_all_levels * 100) / 100 AS percentage
